//! Writes the TS declarations the inspector imports. Run with
//! `UPDATE_TS_TYPES=1` to rewrite the checked-in file.

use ts_rs::{Config, TS};

use super::*;
use crate::view::{EventKind, PromptOrigin};
use crate::wire::{events, memory, sessions, stats};

const OUT: &str = "../../packages/view-core/src/api-types.gen.ts";

const HEADER: &str =
    "// Generated by crates/protocol (cargo test -p peektrace-protocol). Do not edit.\n";

/// One declaration. Answers are read, never changed, so arrays are readonly.
fn decl<T: TS>(cfg: &Config) -> String {
    let d = T::decl(cfg).replace("Array<", "ReadonlyArray<");
    format!("\nexport {d}\n")
}

